	@ParameterizedTest
	@ValueSource(strings = { "EMPTY", "LEGACY", "NATIVE" })
	void firstNativeNamespaceCommitFailureReplaysAgainstCommittedAuthority(String authority) throws Exception {
		Path storeDirectory = directory.resolve("store");
		if (authority.equals("LEGACY")) {
			LmdbCompatibilityFixtures.extract("v2-610-default.zip", storeDirectory);
		}
		ControlledNamespaceStore store = new ControlledNamespaceStore(storeDirectory.toFile());
		SailRepository repository = new SailRepository(store);
		var vf = SimpleValueFactory.getInstance();
		var subject = vf.createIRI("urn:namespace-replay:subject");
		var predicate = vf.createIRI("urn:namespace-replay:predicate");
		var object = vf.createLiteral("namespace and RDF must acknowledge together");
		RuntimeException commitFailure = null;
		try {
			repository.init();
			assertTrue(store.awaitIndexRebuild(10, TimeUnit.SECONDS));
			try (var writer = repository.getConnection()) {
				if (authority.equals("NATIVE")) {
					writer.setNamespace("existing", "urn:existing:");
					assertEquals(Map.of("existing", "urn:existing:"),
							store.getBackingStore().getTripleStore().readNamespaceSnapshot());
				} else {
					assertNull(store.getBackingStore().getTripleStore().readNamespaceSnapshot());
				}
				store.frozenAttempts.set(0);
				AtomicInteger acknowledgments = new AtomicInteger();
				store.addSailChangedListener(event -> acknowledgments.incrementAndGet());
				writer.begin(IsolationLevels.SNAPSHOT_READ);
				writer.add(subject, predicate, object);
				writer.setNamespace("replayed", "urn:replayed:");
				store.failNextCommit.set(true);
				try {
					writer.commit();
				} catch (RuntimeException failure) {
					commitFailure = failure;
				}
				assertEquals(1, store.consumedFailures.get(), "the first real native commit must be consumed");
				if (commitFailure == null) {
					assertTrue(store.frozenAttempts.get() >= 2, "the complete retained input must replay");
					assertEquals(1, acknowledgments.get());
					assertEquals("urn:replayed:", writer.getNamespace("replayed"));
					assertEquals(authority.equals("LEGACY") ? "urn:legacy:" : null, writer.getNamespace("legacy"));
					assertEquals(authority.equals("NATIVE") ? "urn:existing:" : null, writer.getNamespace("existing"));
					assertTrue(writer.hasStatement(subject, predicate, object, false));
				}
			}
		} finally {
			try {
				repository.shutDown();
			} catch (RuntimeException cleanup) {
				if (commitFailure == null) {
					throw cleanup;
				}
				commitFailure.addSuppressed(cleanup);
			}
		}
		RuntimeException observedFailure = commitFailure;
		assertDoesNotThrow(() -> {
			if (observedFailure != null) {
				throw observedFailure;
			}
		}, "a consumed first namespace commit must reconcile its unchanged committed authority and replay");
		SailRepository reopened = new SailRepository(new LmdbStore(storeDirectory.toFile(), configuration()));
		try (var reader = reopened.getConnection()) {
			assertEquals("urn:replayed:", reader.getNamespace("replayed"));
			assertEquals(authority.equals("LEGACY") ? "urn:legacy:" : null, reader.getNamespace("legacy"));
			assertEquals(authority.equals("NATIVE") ? "urn:existing:" : null, reader.getNamespace("existing"));
			assertTrue(reader.hasStatement(subject, predicate, object, false));
		} finally {
			reopened.shutDown();
		}
	}

	@Test
	void lossOfAPublishedNativeEmptyNamespaceSnapshotStillFencesPublication() throws Exception {
		ControlledNamespaceStore store = new ControlledNamespaceStore(directory.resolve("store").toFile());
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			try (var writer = repository.getConnection()) {
				writer.setNamespace("initial", "urn:initial:");
				writer.clearNamespaces();
				assertEquals(Map.of(), store.getBackingStore().getTripleStore().readNamespaceSnapshot());
				writer.begin(IsolationLevels.SNAPSHOT_READ);
				var vf = SimpleValueFactory.getInstance();
				writer.add(vf.createIRI("urn:lost-authority:subject"), vf.createIRI("urn:lost-authority:predicate"),
						vf.createLiteral("must not commit"));
				writer.setNamespace("attempt", "urn:attempt:");
				store.hideNativeAfterFailure = true;
				store.failNextCommit.set(true);
				assertThrows(RepositoryException.class, writer::commit);
			}
			assertThrows(SailException.class, () -> {
				try (var ignored = store.getBackingStore().beginPublication(new Object())) {
				}
			}, "absence cannot silently replace a previously published native authority with an empty fallback");
		} finally {
			store.hideNative.set(false);
			assertThrows(RepositoryException.class, repository::shutDown);
		}
		SailRepository reopened = new SailRepository(
				new LmdbStore(directory.resolve("store").toFile(), configuration()));
		try (var reader = reopened.getConnection()) {
			assertNull(reader.getNamespace("attempt"));
			assertEquals(0L, reader.size());
		} finally {
			reopened.shutDown();
		}
	}

	@ParameterizedTest
	@ValueSource(ints = { 0, 1, 2 })
	void firstMutationPreservesHeldSnapshotAndRollback(int mutation) throws Exception {
		Path storeDirectory = directory.resolve("store");
		LmdbCompatibilityFixtures.extract("v2-610-default.zip", storeDirectory);
		LmdbStore store = new LmdbStore(storeDirectory.toFile(), configuration());
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			assertNull(store.getBackingStore().getTripleStore().readNamespaceSnapshot(),
					"opening must keep the legacy file authoritative until a real namespace mutation");
			try (SailDataset old = store.getBackingStore().getExplicitSailSource().dataset(IsolationLevels.SNAPSHOT);
					var writer = repository.getConnection()) {
				writer.begin();
				if (mutation == 2) {
					writer.clearNamespaces();
				} else {
					writer.setNamespace("legacy", "urn:changed:");
					writer.setNamespace("new", "urn:new:");
				}
				if (mutation == 0) {
					writer.rollback();
				} else {
					writer.commit();
				}
				// The held namespace view is first materialized only after the first mutation/rollback.
				assertEquals("urn:legacy:", old.getNamespace("legacy"));
				assertNull(old.getNamespace("new"));
				assertEquals(mutation == 0 ? "urn:legacy:" : mutation == 1 ? "urn:changed:" : null,
						writer.getNamespace("legacy"));
			}
			if (mutation == 0) {
				assertNull(store.getBackingStore().getTripleStore().readNamespaceSnapshot(),
						"rollback cannot publish an incomplete native namespace authority");
			} else {
				assertEquals(mutation == 1 ? Map.of("legacy", "urn:changed:", "new", "urn:new:") : Map.of(),
						store.getBackingStore().getTripleStore().readNamespaceSnapshot());
			}
		} finally {
			repository.shutDown();
		}
		SailRepository reopened = new SailRepository(new LmdbStore(storeDirectory.toFile(), configuration()));
		try (var connection = reopened.getConnection()) {
			assertEquals(mutation == 0 ? "urn:legacy:" : mutation == 1 ? "urn:changed:" : null,
					connection.getNamespace("legacy"));
			assertEquals(mutation == 1 ? "urn:new:" : null, connection.getNamespace("new"));
		} finally {
			reopened.shutDown();
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void processDeathAcrossTheFirstNativeNamespaceSnapshotKeepsCompleteAuthority(boolean commit) throws Exception {
		Path storeDirectory = directory.resolve("store");
		LmdbCompatibilityFixtures.extract("v2-610-default.zip", storeDirectory);
		Path output = directory.resolve("namespace-child.log");
		Process child = new ProcessBuilder(Path.of(System.getProperty("java.home"), "bin", "java").toString(),
				"-ea", "-cp", System.getProperty("java.class.path"), NamespaceCrashWriter.class.getName(),
				storeDirectory.toString(), Boolean.toString(commit))
						.redirectErrorStream(true)
						.redirectOutput(output.toFile())
						.start();
		try {
			assertTrue(child.waitFor(60, TimeUnit.SECONDS), "the namespace writer must reach the crash cut");
			assertEquals(86, child.exitValue(), () -> read(output));
		} finally {
			if (child.isAlive()) {
				child.destroyForcibly();
			}
		}
		LmdbStore store = new LmdbStore(storeDirectory.toFile(), configuration());
		SailRepository reopened = new SailRepository(store);
		try (var connection = reopened.getConnection()) {
			assertEquals(commit ? "urn:changed:" : "urn:legacy:", connection.getNamespace("legacy"));
			assertEquals(commit ? "urn:new:" : null, connection.getNamespace("new"));
			assertEquals(4, connection.size(), "namespace-only publication must preserve acknowledged statements");
			assertEquals(commit ? Map.of("legacy", "urn:changed:", "new", "urn:new:") : null,
					store.getBackingStore().getTripleStore().readNamespaceSnapshot());
		} finally {
			reopened.shutDown();
		}
	}

