	private static LmdbStoreConfig configuration() {
		return new LmdbStoreConfig().setInlineLiterals(false)
				.setSketchEstimatorEnabled(false)
				.setForceSync(true)
				.setValueDBSize(64L << 20)
				.setTripleDBSize(64L << 20);
	}

	private static final class ControlledNamespaceStore extends LmdbStore {
		private final AtomicBoolean failNextCommit = new AtomicBoolean();
		private final AtomicBoolean hideNative = new AtomicBoolean();
		private final AtomicInteger consumedFailures = new AtomicInteger();
		private final AtomicInteger frozenAttempts = new AtomicInteger();
		private boolean hideNativeAfterFailure;

		private ControlledNamespaceStore(File directory) {
			super(directory, configuration());
		}

		@Override
		LmdbSailStore createBackingStore(File data, StoreProperties properties, LmdbStoreConfig config,
				boolean sketches) throws IOException {
			return new LmdbSailStore(data, properties, config, false, ValueStore::new,
					(dir, nativeProperties, settings, values) -> new TripleStore(dir, nativeProperties, settings,
							values) {
						@Override
						void startTransaction(TxnReplayPolicy.Decision decision) throws IOException {
							super.startTransaction(decision);
							if (decision.frozenReplay) {
								frozenAttempts.incrementAndGet();
							}
						}

						@Override
						int commitWriteTransaction(long transaction) {
							if (failNextCommit.compareAndSet(true, false)) {
								consumedFailures.incrementAndGet();
								hideNative.set(hideNativeAfterFailure);
								mdb_txn_abort(transaction);
								return MDB_MAP_FULL;
							}
							return super.commitWriteTransaction(transaction);
						}

						@Override
						Map<String, String> readNamespaceSnapshot() throws IOException {
							return hideNative.get() ? null : super.readNamespaceSnapshot();
						}
					});
		}
	}

	public static final class NamespaceCrashWriter {
		public static void main(String[] args) {
			var repository = new SailRepository(new LmdbStore(Path.of(args[0]).toFile(), configuration()));
			var connection = repository.getConnection();
			connection.begin();
			connection.setNamespace("legacy", "urn:changed:");
			connection.setNamespace("new", "urn:new:");
			if (Boolean.parseBoolean(args[1])) {
				connection.commit();
			}
			Runtime.getRuntime().halt(86);
		}
	}
